#!/usr/bin/env bash
# .github/lighthouse/serve.sh — serve the built application the way production
# serves it: nginx in front of PHP-FPM, static files from nginx, gzip on.
#
# The Lighthouse budgets in lighthouserc.json are transfer sizes — the gzipped
# bytes nginx sends. `php artisan serve` compresses nothing, so under it the
# stylesheet budget failed on every run and the LCP it measured was one the
# real server never produces. This is a one-server copy of
# deploy/nginx/playndgain.com.conf, including the same gzip snippet, that runs
# as the invoking user on an unprivileged port. No root, so it also works on a
# laptop:
#
#   PORT=8090 .github/lighthouse/serve.sh
#   npx @lhci/cli@0.15.x collect --url=http://127.0.0.1:8090/ && npx @lhci/cli@0.15.x assert
#   .github/lighthouse/serve.sh stop
#
# Overridable: PORT, RUN_DIR, NGINX_BIN, NGINX_CONF_DIR, PHP_FPM_BIN, FPM_LISTEN
# (a unix socket path by default — pass host:port where the run dir is too
# deep for one).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
PORT="${PORT:-8000}"
RUN_DIR="${RUN_DIR:-${RUNNER_TEMP:-/tmp}/playndgain-lighthouse}"
FPM_LISTEN="${FPM_LISTEN:-$RUN_DIR/php-fpm.sock}"
NGINX_BIN="${NGINX_BIN:-$(command -v nginx || true)}"
PHP_FPM_BIN="${PHP_FPM_BIN:-$(command -v php-fpm || command -v php-fpm8.5 || ls /usr/sbin/php-fpm8.* 2>/dev/null | head -n 1 || true)}"

if [ "${1:-start}" = stop ]; then
    for pidfile in "$RUN_DIR/nginx.pid" "$RUN_DIR/php-fpm.pid"; do
        [ -f "$pidfile" ] && kill "$(cat "$pidfile")" 2>/dev/null || true
    done
    exit 0
fi

[ -n "$NGINX_BIN" ] || { echo "serve.sh: nginx not found — set NGINX_BIN" >&2; exit 1; }
[ -n "$PHP_FPM_BIN" ] || { echo "serve.sh: php-fpm not found — set PHP_FPM_BIN" >&2; exit 1; }
[ -f "$ROOT/public/build/manifest.json" ] || { echo "serve.sh: no build — run npm run build first" >&2; exit 1; }

# nginx's own conf directory holds mime.types and fastcgi_params. Ubuntu's
# build says where with --conf-path; a relocatable build only has a prefix,
# and a stale one at that, so the candidates are checked for the file itself.
if [ -z "${NGINX_CONF_DIR:-}" ]; then
    conf_path="$("$NGINX_BIN" -V 2>&1 | sed -n 's/.*--conf-path=\([^ ]*\).*/\1/p')"
    prefix="$("$NGINX_BIN" -V 2>&1 | sed -n 's/.*--prefix=\([^ ]*\).*/\1/p')"
    for candidate in "${conf_path:+$(dirname "$conf_path")}" "${prefix:+$prefix/conf}" /etc/nginx /usr/local/etc/nginx; do
        if [ -n "$candidate" ] && [ -f "$candidate/mime.types" ]; then
            NGINX_CONF_DIR="$candidate"
            break
        fi
    done
fi
[ -n "${NGINX_CONF_DIR:-}" ] && [ -f "$NGINX_CONF_DIR/mime.types" ] || { echo "serve.sh: nginx's mime.types not found — set NGINX_CONF_DIR" >&2; exit 1; }

mkdir -p "$RUN_DIR/tmp" "$RUN_DIR/logs"

case "$FPM_LISTEN" in
    /*) FASTCGI_PASS="unix:$FPM_LISTEN" ;;
    *)  FASTCGI_PASS="$FPM_LISTEN" ;;
esac

cat > "$RUN_DIR/php-fpm.conf" <<EOF
[global]
pid = $RUN_DIR/php-fpm.pid
error_log = $RUN_DIR/logs/php-fpm.log
daemonize = yes

[www]
; Ignored when FPM is not root, which it is not here; the parser wants them anyway.
user = $(id -un)
group = $(id -gn)
listen = $FPM_LISTEN
pm = static
pm.max_children = 4
; The step's environment (APP_ENV, DB_*, …) reaches the workers as it would
; reach artisan serve.
clear_env = no
catch_workers_output = yes
EOF

cat > "$RUN_DIR/nginx.conf" <<EOF
# Generated by .github/lighthouse/serve.sh — deploy/nginx/playndgain.com.conf
# reduced to one unprivileged server on 127.0.0.1:$PORT.
pid "$RUN_DIR/nginx.pid";
error_log "$RUN_DIR/logs/nginx-error.log" warn;
worker_processes 2;

events { worker_connections 256; }

http {
    include "$NGINX_CONF_DIR/mime.types";
    default_type application/octet-stream;
    access_log "$RUN_DIR/logs/nginx-access.log";

    client_body_temp_path "$RUN_DIR/tmp/client_body";
    proxy_temp_path "$RUN_DIR/tmp/proxy";
    fastcgi_temp_path "$RUN_DIR/tmp/fastcgi";
    uwsgi_temp_path "$RUN_DIR/tmp/uwsgi";
    scgi_temp_path "$RUN_DIR/tmp/scgi";

    sendfile on;
    keepalive_timeout 65;

    server {
        listen 127.0.0.1:$PORT;
        server_name localhost;
        root "$ROOT/public";
        index index.php;
        charset utf-8;

        # The same compression production applies — see the snippet's header.
        include "$ROOT/deploy/nginx/snippets/playndgain-gzip.conf";

        location / {
            try_files \$uri \$uri/ /index.php?\$query_string;
        }

        location ~ \.php\$ {
            fastcgi_pass "$FASTCGI_PASS";
            include "$NGINX_CONF_DIR/fastcgi_params";
            fastcgi_param SCRIPT_FILENAME \$realpath_root\$fastcgi_script_name;
        }

        location ^~ /build/ {
            expires 1y;
            add_header Cache-Control "public, immutable";
        }

        location ~* \.(woff2|avif|webp|png|svg|ico)\$ {
            expires 1y;
            add_header Cache-Control "public, immutable";
        }
    }
}
EOF

"$PHP_FPM_BIN" --fpm-config "$RUN_DIR/php-fpm.conf"

# -e (nginx ≥ 1.19.5) keeps the pre-config error log out of /var/log, which
# this user cannot write; older builds only warn about it and carry on.
NGINX_ARGS=(-c "$RUN_DIR/nginx.conf" -p "$RUN_DIR")
if "$NGINX_BIN" -h 2>&1 | grep -q -- '-e filename'; then
    NGINX_ARGS+=(-e "$RUN_DIR/logs/nginx-error.log")
fi
"$NGINX_BIN" "${NGINX_ARGS[@]}"

echo "serve.sh: nginx + php-fpm serving $ROOT/public on http://127.0.0.1:$PORT (gzip on, logs in $RUN_DIR/logs)"
